DROP TABLE IF EXISTS `licenses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `licenses` (
  `id` varchar(255) COLLATE utf8_bin NOT NULL,
  `sensorlist` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `excludesensorlist` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `app` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `imei` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `auth` varchar(255) COLLATE utf8_bin DEFAULT NULL,
  `active` int(11) DEFAULT NULL,
  `customerId` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `customerId` (`customerId`),
  CONSTRAINT `licenses_ibfk_1` FOREIGN KEY (`customerId`) REFERENCES `customers` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

